CREATE TABLE IF NOT EXISTS tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_id uuid NOT NULL REFERENCES trips(id), passenger_id uuid NOT NULL REFERENCES users(id), seat_code text NOT NULL, manual_code text UNIQUE NOT NULL, qr_payload jsonb NOT NULL, base_fare_ngn bigint NOT NULL, platform_fee_ngn bigint NOT NULL DEFAULT 20, paystack_fee_ngn bigint NOT NULL, payment_reference text UNIQUE, status text NOT NULL DEFAULT 'PENDING', UNIQUE(trip_id,seat_code));
CREATE TABLE IF NOT EXISTS refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES tickets(id), percent int NOT NULL CHECK(percent IN (40,80,100)), amount_ngn bigint NOT NULL CHECK(amount_ngn>=0), destination text NOT NULL CHECK(destination IN ('WALLET','ORIGINAL')), idempotency_key text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
